<template><div style='display:flex;gap:8px;'><button @click='metronome=!metronome'>{{ metronome ? 'Metronome: ON' : 'Metronome: OFF' }}</button></div></template><script setup lang='ts'>import { ref, watchEffect } from 'vue'; import { useProjectStore } from '../stores/project'; const project=useProjectStore(); const metronome=ref(false); let interval:any=null; watchEffect(()=>{ if(metronome.value){ const ctx=project.audioCtx; const osc=ctx.createOscillator(); const gain=ctx.createGain(); gain.gain.value=0; osc.connect(gain); gain.connect(ctx.destination); osc.start(); let beat=0; interval=setInterval(()=>{ const t=ctx.currentTime; osc.frequency.setValueAtTime(beat===0?1000:800,t); gain.gain.cancelScheduledValues(t); gain.gain.setValueAtTime(0.3,t); gain.gain.exponentialRampToValueAtTime(0.0001,t+0.06); beat=(beat+1)%4; }, 60000/project.bpm); } else { if(interval){ clearInterval(interval); interval=null; } } });</script>